// GHL's webhook action lets the payload be shaped in the UI, so accept the
// obvious spellings rather than depending on one exact layout.
const raw = $input.first().json;
const b = (raw && raw.body && typeof raw.body === 'object') ? raw.body : raw;

// GHL sends BOTH shapes at once:
//   customData - whatever we mapped in the workflow's Webhook action. Explicit,
//                flat, and the thing we actually control.
//   message    - GHL's own object, e.g. { type: 2, body: "Okay send details" }.
// Read customData first. The native object is the fallback, and it must be
// unwrapped: an earlier version stringified it whole and every reply arrived as
// the literal text "[object Object]" with a type of "2", so every single one
// was discarded as "not an SMS".
const asObj = (v) => {
  if (v && typeof v === 'object') return v;
  if (typeof v === 'string' && v.trim().startsWith('{')) {
    try { return JSON.parse(v); } catch (e) { return {}; }
  }
  return {};
};
const cd  = asObj(b.customData || b.custom_data);
const msg = asObj(b.message);

// Only ever accept a primitive. This is the guard that was missing.
const str = (v) => (v === undefined || v === null || typeof v === 'object')
  ? '' : String(v).trim();

const pick = (...cands) => {
  for (const v of cands) { const s = str(v); if (s) return s; }
  return '';
};

const contactId = pick(cd.contactId, cd.contact_id, b.contact_id, b.contactId,
                       (b.contact || {}).id, b.id);
// b.message is included as a PLAIN value too - str() rejects it when it is
// GHL's object, and accepts it when a simpler integration posts a string.
const text = pick(cd.message, cd.body, cd.text, msg.body,
                  b.message, b.body, b.text, b.messageBody);
const direction = pick(cd.direction, msg.direction, b.direction).toLowerCase();
const conversationId = pick(cd.conversationId, b.conversationId, b.conversation_id,
                            msg.conversationId);

// Type arrives either as our own word ("SMS") or as GHL's numeric enum.
const TYPE_NUM = { 1: 'call', 2: 'sms', 3: 'email', 4: 'facebook', 5: 'gmb',
                   6: 'instagram', 7: 'whatsapp' };
const rawType = pick(cd.type, cd.messageType, msg.type, b.type, b.messageType);
const type = (TYPE_NUM[rawType] || rawType).toLowerCase();

// Never act on our own outbound - that is how a bot ends up talking to itself.
const isOutbound = direction === 'outbound';
// Blank type means the payload did not include it; treat that as SMS rather
// than dropping real replies, but never treat an explicit email/call as one.
const isSms = !type || type.indexOf('sms') !== -1 || type.indexOf('text') !== -1;

let ignore = '';
if (!contactId) ignore = 'no contactId in the payload';
else if (isOutbound) ignore = 'outbound message';
else if (!isSms) ignore = 'not an SMS (' + type + ')';
else if (!text) ignore = 'empty message body';

// Opt-out is decided here, on the raw text, before anything else runs. No
// model, no scoring, no ambiguity - this path must be boring and total.
const STOP = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit',
              'remove', 'removeme', 'optout', 'opt out', 'unsub', 'donotcontact'];
const bare = String(text).toLowerCase().replace(/[^a-z ]/g, '').trim();
const optOut = STOP.indexOf(bare) !== -1
            || STOP.indexOf(bare.replace(/\s/g, '')) !== -1
            || /\b(stop texting|take me off|remove me|do not contact|dont contact)\b/.test(bare);

return [{ json: {
  ignore, actionable: !ignore,
  contactId, conversationId, text, direction, type, optOut
} }];

// Pick which deal this reply is about, and decide whether Claude is even
// needed. An opt-out short-circuits everything.
const n = $('Normalize Reply').first().json;
const contact = ($input.first().json.contact) || $input.first().json || {};

const defs = ($('Fetch Field Definitions').first().json.customFields) || [];
const ID = {}, NAME = {};
for (const d of defs) { ID[d.name] = d.id; NAME[d.id] = d.name; }
const prior = {};
for (const f of (contact.customFields || [])) {
  const nm = NAME[f.id];
  if (nm) prior[nm] = (f.value !== undefined ? f.value : f.fieldValue);
}

const arr = (v) => v == null ? [] : (Array.isArray(v) ? v : String(v).split(/[;,]/));
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const source = arr(prior['buy_source']).map(norm);

// Reply from the SAME number the buyer already has saved for us. Falling back
// to a constant would answer from a line they have never seen, in a new thread,
// which is exactly the confusion the sticky number exists to prevent.
const KNOWN_NUMBERS = ['+17868414589', '+17864345766', '+17867306407', '+19543292967'];
const storedFrom = String(prior['buy_from_number'] || '').trim();
const fromNumber = KNOWN_NUMBERS.indexOf(storedFrom) !== -1 ? storedFrom : KNOWN_NUMBERS[0];

// InvestorLift buyers never auto-send, whatever they say. They raised a hand on
// a public listing; some of them are competing wholesalers fishing for the
// address. A human decides what those people get.
const investorLift = source.indexOf('investorlift') !== -1;

// Which deal? The open Buyer Interest opportunities, newest first.
const opps = ($('Fetch Open Opportunities').first().json.opportunities) || [];
const stageName = {};
try {
  const pipes = ($('Fetch Pipelines').first().json.pipelines) || [];
  const bi = pipes.find(p => (p.name || '').toLowerCase().indexOf('buyer interest') !== -1);
  for (const s of ((bi && bi.stages) || [])) stageName[s.id] = s.name;
  var BI = bi;
} catch (e) { var BI = null; }

// Which opportunity is this reply about? Any stage BEFORE 'Info Sent' means
// we have contacted them and not yet sent the details - so they are still
// waiting on us and a reply should be acted on.
//
// Deliberately by POSITION, not by a list of stage names. The first version
// matched only 'reached out', so the moment a 'Called' stage was added, a
// buyer we phoned and then moved would silently stop getting auto-responses:
// no deal found, haveDeal gate closed, nothing sent, no error. Position means
// any early stage added later just works.
const stages = (BI && BI.stages) || [];
const posOf = {};
stages.forEach((s, i) => { posOf[s.id] = (s.position != null ? s.position : i); });
const infoSent = stages.find(s => (s.name || '').toLowerCase().indexOf('info sent') !== -1);
// No Info Sent stage at all? Fall back to the first stage only, which is the
// old behaviour - conservative rather than replying to a closed deal.
const cutoff = infoSent ? posOf[infoSent.id] : 1;

const reachedOut = opps
  .filter(o => posOf[o.pipelineStageId] !== undefined && posOf[o.pipelineStageId] < cutoff)
  .sort((a, b) => new Date(b.updatedAt || b.createdAt || 0) - new Date(a.updatedAt || a.createdAt || 0));

// Read the address from the opportunity's own field, never by parsing its
// NAME. The name format is cosmetic and has already changed once - it was
// "{address} - {buyer}" and became "{buyer} - {address}", which silently made
// this return the buyer's name as the address. opp_deal_address exists exactly
// so this does not depend on a display string. Five opportunities currently
// carry a name from one deal and an opp_deal_address from another, which is
// precisely the disagreement this avoids.
const OPP_DEAL_ADDRESS = '23Qr6cqR1IP1zFknf5Wn';
// The SAME field comes back under three different key names depending on the
// endpoint: `fieldValue` from GET /opportunities/{id}, `fieldValueString` from
// GET /opportunities/search, and `value` on contacts. Accept all three.
const oppField = (o, id) => {
  const hit = ((o && o.customFields) || []).find(f => f.id === id);
  if (!hit) return '';
  const v = hit.fieldValue !== undefined ? hit.fieldValue
          : hit.fieldValueString !== undefined ? hit.fieldValueString
          : hit.value;
  return v === undefined || v === null ? '' : String(v).trim();
};

// WHICH deal is this reply about?
//
// buy_last_deal answers it, and it is EVIDENCE rather than inference: the blast
// stamps it on the contact at send time, so it names the property this buyer was
// actually texted. Everything below it is a guess about the state of a board.
//
// 2026-08-22 is why this order changed. A blast crashed after sending but before
// creating its opportunities, so the newest open opportunity was still the
// PREVIOUS deal - buyers who asked about Kendall were sent Hialeah. Backfilling
// the opportunities fixed that case, but not the shape of it: "newest updatedAt"
// flips the moment somebody drags an older card to a new stage, and ordinary
// pipeline work must never change what a buyer is told.
const lastDeal = String(prior['buy_last_deal'] || '').trim();
const matched = lastDeal
  ? reachedOut.find(o => norm(oppField(o, OPP_DEAL_ADDRESS)) === norm(lastDeal))
  : null;
const deal = matched || reachedOut[0] || null;
const dealSource = matched ? 'buy_last_deal'
                 : (deal ? 'newest open opportunity' : 'none');

// Ambiguity is about whether we had to GUESS. Matching buy_last_deal is not a
// guess, however many opportunities happen to be open at once.
const ambiguous = !matched && reachedOut.length > 1;

const address = (matched ? lastDeal
              : (deal ? oppField(deal, OPP_DEAL_ADDRESS) : '')) || lastDeal;

const nextStage = (BI && BI.stages || []).find(s => (s.name || '').toLowerCase() === 'info sent');

const SYSTEM = [
  'You classify a single inbound SMS from a cash buyer replying to a wholesale property blast.',
  'Return exactly one intent.',
  '"interested" means they want the property details, the address, the price, photos, or a showing - any signal they want to go further on THIS deal.',
  '"not_interested" means they decline, say it is not for them, or say wrong number.',
  '"question" means they are asking something unrelated to wanting the deal - who we are, how we got their number, general enquiry.',
  '"opt_out" means they want to stop receiving messages.',
  '"unclear" means you cannot tell.',
  'Be conservative: if a reply could plausibly be a decline, it is NOT interested. Choose "unclear" over guessing.',
  'confidence is "high" only when the reply is unambiguous.'
].join(' ');

const claudeBody = {
  model: 'claude-opus-5',
  max_tokens: 2000,
  system: SYSTEM,
  messages: [{ role: 'user', content: 'Buyer reply:\n\n' + n.text }],
  output_config: { format: { type: 'json_schema', schema: {
    type: 'object',
    properties: {
      intent: { type: 'string', enum: ['interested', 'not_interested', 'question', 'opt_out', 'unclear'] },
      confidence: { type: 'string', enum: ['high', 'low'] },
      objection: { type: 'string', description: 'Their objection in a few words, or empty if none.' },
      reason: { type: 'string', description: 'One short sentence on why you chose this intent.' }
    },
    required: ['intent', 'confidence', 'objection', 'reason'],
    additionalProperties: false
  } } }
};

return [{ json: {
  ...n,
  needsClassification: !n.optOut,
  investorLift,
  priorReplies: Number(prior['buy_replies'] || 0) || 0,
  fieldIds: ID,
  dealOppId: deal ? deal.id : null,
  dealStageId: deal ? deal.pipelineStageId : null,
  address, ambiguous, fromNumber, dealSource,
  openAtReachedOut: reachedOut.length,
  infoSentStageId: nextStage ? nextStage.id : null,
  pipelineId: BI ? BI.id : null,
  claudeBody
} }];

// Turn the classification into three concrete things: what to write on the
// contact, whether to move the opportunity, and whether to text.
const p = $('Prepare Reply Context').first().json;
const ID = p.fieldIds || {};

let ai = { intent: 'unclear', confidence: 'low', objection: '', reason: '' };
let aiError = null;
if (p.optOut) {
  ai = { intent: 'opt_out', confidence: 'high', objection: '', reason: 'matched the opt-out keyword list' };
} else {
  try {
    const res = $input.first().json;
    const t = (res.content || []).find(b => b.type === 'text');
    ai = JSON.parse(t.text);
  } catch (e) { aiError = String(e); }
}

// ---- auto-send kill switch ----
// ON from 2026-08-25 at Jorge's request. It was off from 2026-08-22 while the
// team answered the Hialeah deal by hand.
// When false this blocks OUTBOUND TEXT ONLY - everything else still runs:
// the reply is recorded, the objection is captured, buy_replies increments, and
// an opt-out still writes DNC and Opted Out - because those are compliance and
// data, not outreach. Deactivating the whole workflow would have silently
// stopped honouring STOP, which is the one thing that must never stop.
// Set to false to hold sends for a human again.
const AUTO_SEND = true;

const optOut = p.optOut || ai.intent === 'opt_out';
const nowIso = new Date().toISOString();

// ---- contact update: the reply is recorded no matter what it said ----
const cf = [];
const put = (name, value) => { if (ID[name]) cf.push({ id: ID[name], value }); };
put('buy_last_responded', nowIso);
put('buy_replies', Number(p.priorReplies || 0) + 1);
if (ai.objection) put('buy_objection_last', String(ai.objection).slice(0, 500));

if (optOut) {
  // Consent stays FACTUAL. They opted out; that is what the record says.
  put('buy_status', 'DNC');
  put('buy_consent_status', 'Opted Out');
}

// ---- should the full house post go out? every gate must pass ----
// haveDeal is deliberately NOT a gate. 2026-08-26: W2 sends the texts and
// creates the Buyer Interest cards afterwards, so a buyer who replies during
// the blast has no card yet. Odette Martinez asked for the address 22 seconds
// before hers existed - classified interested/high, correct in every way, and
// held. The gate punished the fastest buyers, which are the ones worth
// answering fastest. What decides WHAT to say is the ADDRESS; the card only
// decides whether a stage can be moved, and a missing one is not a reason to
// leave a buyer waiting.
const gates = {
  notOptOut: !optOut,
  interested: ai.intent === 'interested',
  confident: ai.confidence === 'high',
  // Segment 1 buyers came off a public listing. Some are competing wholesalers
  // fishing for the address, so a human decides what they get.
  notInvestorLift: !p.investorLift,
  haveAddress: !!p.address,
  autoSendEnabled: AUTO_SEND
};
const send = Object.keys(gates).every(k => gates[k]);
const blockedBy = Object.keys(gates).filter(k => !gates[k]);

let outcome;
if (optOut) outcome = 'opted out - suppressed, nothing sent';
else if (send) outcome = 'interested - sending the full house post';
else if (!AUTO_SEND && ai.intent === 'interested') outcome = 'interested - auto-send is off, held for a human';
else if (p.investorLift && ai.intent === 'interested') outcome = 'interested, but InvestorLift - held for a human';
else outcome = ai.intent + ' - held for a human';

return [{ json: {
  ...p,
  intent: ai.intent, confidence: ai.confidence, objection: ai.objection || '',
  reason: ai.reason || '', aiError,
  optOut, send, blockedBy, outcome,
  contactBody: { customFields: cf },
  // Opt-outs go to Passed; a confirmed send goes to Info Sent.
  // Only movable when a card actually exists. When it does not, the send
  // still happens and W2 creates the card moments later at Reached Out.
  moveStageId: optOut ? null : (send && p.dealOppId ? p.infoSentStageId : null),
  needsHuman: !send && !optOut
} }];

// Pull the saved SMS post for this exact address. If it is not there, do NOT
// improvise a message - send nothing and let a human handle it.
const d = $('Decide Action').first().json;
const recs = ($input.first().json.records) || [];
const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
const want = norm(d.address);
const hit = recs.find(r => norm(r.properties && r.properties.prop_address) === want);
const post = hit ? String(hit.properties.prop_sms_post || '') : '';
return [{ json: { ...d, propertyFound: !!hit, post, canSend: !!post } }];

const d = $('Decide Action').first().json;
let sent = false;
try { sent = $('Send Full House Post').all().some(x => x.json && (x.json.messageId || x.json.conversationId)); } catch (e) {}

return [{ json: {
  ok: true,
  contactId: d.contactId,
  reply: d.text,
  intent: d.intent,
  confidence: d.confidence,
  outcome: d.outcome,
  fullPostSent: sent,
  movedTo: d.send && sent ? 'Info Sent' : null,
  needsHuman: d.needsHuman,
  ambiguousDeal: d.ambiguous,
  openAtReachedOut: d.openAtReachedOut,
  address: d.address,
  blockedBy: d.blockedBy,
  aiError: d.aiError
} }];
